script:
frappe.ui.form.on("Purchase Invoice", {
    supplier(frm) {
        setTimeout(() => set_supplier_tax_category(frm, true), 1000);
    },

    supplier_address(frm) {
        setTimeout(() => set_supplier_tax_category(frm, true), 300);
    },

    validate(frm) {
        return set_supplier_tax_category(frm, false);
    }
});


async function set_supplier_tax_category(frm, trigger_change = false) {
    if (!frm.doc.supplier_address || frm.doc.docstatus !== 0) {
        return;
    }

    const result = await frappe.db.get_value(
        "Address",
        frm.doc.supplier_address,
        ["gstin", "gst_state_number", "gst_state"]
    );

    const address = result?.message || {};

    const gstin = String(address.gstin || "")
        .trim()
        .replace(/\s+/g, "")
        .toUpperCase();

    if (!gstin) {
        return;
    }

    const state_code = gstin.substring(0, 2);
    const tax_category = state_code === "33" ? "In-State" : "Out-State";

    if (frm.doc.tax_category !== tax_category) {
        if (trigger_change) {
            await frm.set_value("tax_category", tax_category);
        } else {
            frm.doc.tax_category = tax_category;
            frm.refresh_field("tax_category");
        }
    }
}
